import{c as t,Q as a,j as o,m as n}from"./chunks/framework.BXc4yaFE.js";const c=JSON.parse('{"title":"I Turned Claude Fable Into The Ultimate Second Brain","description":"","frontmatter":{},"headers":[],"relativePath":"research/tweets/2026-06-10-@nateherk-399269.md","filePath":"research/tweets/2026-06-10-@nateherk-399269.md","lastUpdated":1785909234000}'),i={name:"research/tweets/2026-06-10-@nateherk-399269.md"};function s(r,e,l,h,d,u){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="i-turned-claude-fable-into-the-ultimate-second-brain" tabindex="-1">I Turned Claude Fable Into The Ultimate Second Brain <a class="header-anchor" href="#i-turned-claude-fable-into-the-ultimate-second-brain" aria-label="Permalink to &quot;I Turned Claude Fable Into The Ultimate Second Brain&quot;">​</a></h1><p><strong>來源</strong>：<a href="https://x.com/nateherk/status/2064572363652399269" target="_blank" rel="noreferrer">@nateherk</a>（Nate Herk）<br><strong>日期</strong>：2026-06-10<br><strong>類型</strong>：Twitter Article<br><strong>統計</strong>：❤️ 180 · 🔁 22 · 👁 107055 · 🔖 448</p><hr><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Permalink to &quot;TL;DR&quot;">​</a></h2><p>Four Cs 框架（Context/Connections/Capabilities/Cadence）打造工具中立 AI OS；Folders+Markdown 設計可在任何 model 間切換；安全原則「Keys not prompts」；含 Claude Fable 定價分析與 Lightning Round Q&amp;A。</p><hr><h2 id="核心論點" tabindex="-1">核心論點 <a class="header-anchor" href="#核心論點" aria-label="Permalink to &quot;核心論點&quot;">​</a></h2><ol><li>AI OS 從「設定一個預設」開始（不是架構），先建 Second Brain 再疊 OS</li><li>Four Cs 框架：Context（身份/業務）→ Connections（Live 資料）→ Capabilities（Skills/自動化）→ Cadence（日常節奏）</li><li>安全原則：「A prompt is never a permission layer. Keys, not prompts.」（Scoped API keys）</li><li>Tool-agnostic 設計：所有東西都是 folders + markdown，可切 Codex/Claude/任意 model</li><li>Claude Fable = Mythos 5.0，含更多 cyber guardrails；2× Opus 價格（$10/M input, $50/M output）</li></ol><hr><h2 id="關鍵數據-工具-引用" tabindex="-1">關鍵數據 / 工具 / 引用 <a class="header-anchor" href="#關鍵數據-工具-引用" aria-label="Permalink to &quot;關鍵數據 / 工具 / 引用&quot;">​</a></h2><ul><li>定價：Claude Fable $10/M input, $50/M output（Opus 2×）</li><li>訂閱：June 9-22 在訂閱方案內，之後轉 usage credits</li><li>個人成本：$200/月計畫，多為知識工作（非重量 coding）</li><li>工具：Claude Code、Codex（雙軌比較）、.claude/.codex/.agents 三目錄並行</li></ul><hr><h2 id="批判性觀察" tabindex="-1">批判性觀察 <a class="header-anchor" href="#批判性觀察" aria-label="Permalink to &quot;批判性觀察&quot;">​</a></h2><ol><li>缺乏 Fable 與 Opus 的具體能力比較數據，定價資訊為主要新增內容</li><li>Four Cs 框架實用但偏個人經驗分享，缺乏可量測的成效指標</li><li>GitHub repo 連結未在文中給出（指向回覆 + Skool 社群）</li></ol><hr><h2 id="_5-維度評分" tabindex="-1">5 維度評分 <a class="header-anchor" href="#_5-維度評分" aria-label="Permalink to &quot;5 維度評分&quot;">​</a></h2><table tabindex="0"><thead><tr><th>維度</th><th>分數</th><th>說明</th></tr></thead><tbody><tr><td>A. Workspace 可行動性 (30%)</td><td>8</td><td>Four Cs + Lightning Round Q&amp;A + GitHub repo 指引</td></tr><tr><td>B. 創新性 (20%)</td><td>6</td><td>Tool-agnostic 設計概念有價值</td></tr><tr><td>C. 證據品質 (20%)</td><td>6</td><td>個人經驗 + 定價，缺獨立驗證</td></tr><tr><td>D. 技術深度 (15%)</td><td>6</td><td>框架清楚但實作較薄</td></tr><tr><td>E. 泛化性 (15%)</td><td>8</td><td>適用所有知識工作者</td></tr></tbody></table><p><strong>加權總分：6.90 → Agent</strong></p><hr><h2 id="整合決策" tabindex="-1">整合決策 <a class="header-anchor" href="#整合決策" aria-label="Permalink to &quot;整合決策&quot;">​</a></h2><p><strong>Agent</strong> — Four Cs AI OS 建構框架可作為個人 AI 工作系統設計模板</p><hr><h2 id="全文" tabindex="-1">全文 <a class="header-anchor" href="#全文" aria-label="Permalink to &quot;全文&quot;">​</a></h2><p>My whole life and business now sit in one place, and Claude Fable understands it better than I do.</p><p>It&#39;s not just answering questions about my business. It&#39;s automating it.</p><p>I&#39;ve been building this AI operating system for months. I didn&#39;t throw it together because a new model dropped. I just spent the day seeing how Fable slots into what I already had.</p><p>Here&#39;s how the whole thing is set up, how I keep improving it, and the way I think about it day to day.</p><h2 id="tl-dr-1" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr-1" aria-label="Permalink to &quot;TL;DR&quot;">​</a></h2><p>→ Claude Fable just dropped, basically Claude Mythos 5.0 with more cyber guardrails baked in</p><p>→ It&#39;s 2x the price of Opus ($10/M input, $50/M output) and on subscription only from June 9 through June 22 before it moves to usage credits</p><p>→ My AI OS runs on the Four Cs: Context, Connections, Capabilities, Cadence</p><p>→ The first two Cs are your second brain. The last two are your AI OS.</p><p>→ A prompt is never a permission layer. Keys, not prompts.</p><p>→ At the end of the day it&#39;s all folders and markdown files, so it&#39;s tool agnostic</p><h2 id="claude-fable-quickly" tabindex="-1">Claude Fable, Quickly <a class="header-anchor" href="#claude-fable-quickly" aria-label="Permalink to &quot;Claude Fable, Quickly&quot;">​</a></h2><p>Fable is basically Claude Mythos 5.0 with more cyber guardrails baked in.</p><p>Mythos is the model Anthropic has been teasing for months. So powerful it&#39;s not generally available, only open to heavy cyber and infrastructure partners in Project Glasswing.</p><p>Two things to know before you jump in.</p><p>It&#39;s only on your subscription from today (June 9) through June 22, then it switches to usage credits. So get in and play with it over the next two weeks.</p><p>And it&#39;s 2x as expensive as Opus. $10 for a million input tokens, $50 for a million output. It eats your subscription faster than Opus does.</p><h2 id="it-starts-with-a-default-not-architecture" tabindex="-1">It Starts With A Default, Not Architecture <a class="header-anchor" href="#it-starts-with-a-default-not-architecture" aria-label="Permalink to &quot;It Starts With A Default, Not Architecture&quot;">​</a></h2><p>Most of this is a mindset shift. An adoption problem. A habits shift.</p><p>Before this, I was opening different AI tools, different subscriptions, custom projects and custom GPTs. It felt productive, and it was, but I was repeating myself. It never felt like a co-founder that actually knew what was going on in my life and business.</p><p>Step one is to close all those tabs and default to one harness. Claude Code, Codex, whatever you want. Most of you want Claude Code.</p><p>Do everything through it and you start building up context, memory, and preferences. That&#39;s the way to do it.</p><p>An OS doesn&#39;t start with architecture. It starts with a default.</p><p>From there I think about it in two layers.</p><p>The second brain is the first piece, and without it you can&#39;t have an AI OS. The second brain is your knowledge. Does this thing know what&#39;s going on in your business, your life, your clients, your YouTube channel, and can you ask it questions about all of it?</p><p>Once you have a second brain, you build the OS on top. Skills, automations, actually working out of it as your operating system instead of Apple or Windows.</p><h2 id="the-four-cs" tabindex="-1">The Four Cs <a class="header-anchor" href="#the-four-cs" aria-label="Permalink to &quot;The Four Cs&quot;">​</a></h2><p>The framework I use to build and maintain my AI OS is the Four Cs, taken in order.</p><p>1️⃣ Context → who you are, who your business is</p><p>2️⃣ Connections → can your second brain reach live data, not just static notes</p><p>3️⃣ Capabilities → the skills, agents, automations, and pipelines you build</p><p>4️⃣ Cadence → turning those capabilities into things that run on their own while you sleep</p><p>The first two are your second brain. The last two are your AI OS.</p><p>This is the order I teach. It matters even if you&#39;re already set up, because you might need to upskill your team later, or go sell AI OS setups to a business. This is the framework.</p><h2 id="context-your-routing-tree" tabindex="-1">Context: Your Routing Tree <a class="header-anchor" href="#context-your-routing-tree" aria-label="Permalink to &quot;Context: Your Routing Tree&quot;">​</a></h2><p>Context is your routing tree, and my Claude.md is the router.</p><p>It has some goal and process stuff, but mostly it points the agent to where things live. The rules, the references, the skills, the other projects, the wikis. For my knowledge base I give it the exact wiki path, the hot cache, the master index, and the way to look through it.</p><p>People ask me constantly: at what point is it too much context, and how do you know when to split things up?</p><p>So far mine has not been too much, because when I ask it to find something it finds it fast. I&#39;m watching it. If it searches for five minutes for a file I know the location of, that&#39;s a signal to update the architecture.</p><p>We&#39;ve heard context engineering, prompt engineering, harness engineering. I think architecture engineering is the next art, and there&#39;s no single right answer. My pulse check is simple. Is it intuitive to me? Could I manually drill through my folders and find what I need, and can my agent do the same?</p><p>One thing I switched to recently that I get a lot of questions about is a folder I call Other Worlds. It holds my other Claude Code projects, the stuff I used to open in completely separate repos.</p><p>I moved everything I use frequently into my Herk-2 project for two reasons.</p><p>→ Syncing. I push Herk-2 to GitHub, pull it on my laptop, and everything comes with it. I don&#39;t have to push six different projects before I switch machines.</p><p>→ Reach. My main OS now has context into my book project, my website, my video edits, my token dashboard. It can CD around and find what it needs. I love that I just open Herk-2 and get to anything.</p><p>These aren&#39;t small projects either. My YouTube OS alone has projects, references, and transcripts with deep drill-downs.</p><p>And even with all of that, when I run /context in my main directory I&#39;m only at about 40,000 tokens starting off. Most of that is system tools and a bit of memory. Markdown files won&#39;t be the bottleneck for a long time.</p><p>There&#39;s no right or wrong answer here. You&#39;ll know something&#39;s off if you&#39;re burning tokens or your agent searches for 20 minutes. Otherwise you get to orchestrate your own architecture. As long as the paths are intuitive and the agent isn&#39;t wasting tokens, you&#39;re fine.</p><h2 id="connections-static-vs-live-data" tabindex="-1">Connections: Static vs Live Data <a class="header-anchor" href="#connections-static-vs-live-data" aria-label="Permalink to &quot;Connections: Static vs Live Data&quot;">​</a></h2><p>Some of your data is static. Your background, meeting transcripts, last year&#39;s progress and achievements.</p><p>Connections are the data that&#39;s constantly changing. Your ClickUp messages to the team, your emails, your QuickBooks P&amp;L.</p><p>To find yours, start with a first tier. On a weekly basis, what apps do you open? What bookmarks live in Chrome? Where do you go to talk to people, internal or external? Those high-priority things are what you pull in first.</p><p>If you&#39;re stuck, think revenue, customers, calendar, comms, tasks, meetings, knowledge. Where does each one live?</p><p>For me, Skool is revenue and customers. Customers also on YouTube. Revenue in Stripe and QuickBooks. Calendar in Google Workspace. Comms in Google Workspace, ClickUp, and Slack.</p><p>Most of those connections happen through API keys and endpoints, which I&#39;ll get to.</p><p>The gut check for this whole layer: if you opened Claude Code right now and asked it about you and your business, would the answer sound like a stranger, or like a teammate?</p><h2 id="what-fable-already-knows-about-me" tabindex="-1">What Fable Already Knows About Me <a class="header-anchor" href="#what-fable-already-knows-about-me" aria-label="Permalink to &quot;What Fable Already Knows About Me&quot;">​</a></h2><p>Two quick examples of how well it knows me.</p><p>First, I ran /goal and asked it to look through the project, figure out what it knows about me, my channel, and our business, and build a video explaining my journey using hyperframes.</p><p>It pulled the real picture. Nate Herk, AI automation, Chicago founder, creator, dog dad. Teaching everyday people to build with AI. 41 videos in 2024, 261 in 2025. The free 8-hour course with over 1.5 million views. The flywheel from YouTube to AIS free to AIS paid to high-ticket coaching. A 13-person team at Uppit AI, the core company that owns everything across our ventures. The pivot from n8n to Claude Code this year, same mission, sharper tools.</p><p>One thing it got wrong: it said 620,000 subscribers when I&#39;m closer to 800K now. That&#39;s the static data problem. It used the last refresh. If I asked it to pull subscribers live, it would update that number on the spot. Worth calling out so you understand the tradeoff.</p><p>The whole video came from one prompt.</p><p>The annoying part is that Fable is not cheap. When I first stress tested it, I burned my entire $200/month max plan five-hour session in a little over an hour. It eats your limit noticeably faster than Opus, so be careful.</p><p>Second example, also a one-shot /goal that finished in about 21 minutes. I asked it to take all my transcripts and the relationships between them and put them into a clean interface anyone could click through.</p><p>It built a front end with ideas, tools and harnesses, and techniques. Click one and it shows the real connections. Agentic Workflows loops into Context Windows. Claude Code connects to Codex, Open Claw, Hermes Agent, basically everything. It even shows which videos each concept came up in, and added a top nav with &quot;I&#39;m new here,&quot; &quot;I build things,&quot; and &quot;I run a business&quot; entry points.</p><p>To do that it had to build the UI, read through my actual YouTube transcripts, map the real relationships, and think about the user journey. Very impressive for one prompt.</p><p>For most of this I don&#39;t use a database. It&#39;s markdown files and Karpathy&#39;s LLM wiki approach with Obsidian.</p><p>And about the model itself: benchmarks aren&#39;t the best way to judge. The harness and the way you use it matter more, and a lot of it is feel. Karpathy put it well, that you can give Fable far more ambitious tasks than you&#39;re used to and the model just &quot;gets it.&quot; That matches my experience. It understands what I&#39;m going for more often.</p><p>It still has rough edges. Sometimes it&#39;s slow. Sometimes the cyber safeguards fire when they shouldn&#39;t, telling me it can&#39;t do something. The safeguards are a little too trigger happy for launch, which makes sense, and they&#39;ll get tuned as the community gives feedback.</p><h2 id="capabilities-skills-agents-assembly-lines" tabindex="-1">Capabilities: Skills, Agents, Assembly Lines <a class="header-anchor" href="#capabilities-skills-agents-assembly-lines" aria-label="Permalink to &quot;Capabilities: Skills, Agents, Assembly Lines&quot;">​</a></h2><p>Once you have context and connections, capabilities are what you can actually do.</p><p>This is another adoption test. Can you default to doing the work inside your AI OS instead of opening a Chrome tab? Before you send that email or pull that report, open your VS Code instead.</p><p>When you bring in a tool, check if it has an API endpoint. If yes, grab it. A CLI? Grab that. I lean on CLIs and APIs over MCP servers because I get more control and they tend to be cheaper, but MCP works too.</p><p>Skills don&#39;t have to be some 10-step monster. A skill can just be a prompt. If you write the same thing every Monday morning or Friday evening, turn it into a skill. If you brainstorm something with Claude Code and like the result, tell it to turn that into a skill so next week it&#39;s faster.</p><p>Your skill won&#39;t be perfect on the first try, and that&#39;s the point. Every time you use it, that&#39;s data. Tell it what you liked, what you didn&#39;t, update it, run it again. I have 20-plus skills plus a bunch of global ones, and every single time I use one I give feedback and say update the skill. A generate-image skill I built four months ago is still changing because my preferences, the models, and the endpoints all change. There&#39;s no finished product.</p><p>I think in assembly lines, going back to my n8n days. One AI doing one thing really well. One makes the wheels, one the axles, one the hood, and it comes together at the end.</p><p>If you cram everything into one session it blurs and you hit context rot. Instead I work in phases. Spin up an agent to research X, take the output, /clear, bring it into the draft, then take the draft into a polishing pass. Chain the outputs through specialized agents.</p><p>For parallel work, delegate. Especially with Fable&#39;s price, push parallel tasks to cheaper workers like Sonnet or Haiku and get one clean summary back. That&#39;s exactly what dynamic workflows do.</p><h2 id="cadence-earning-the-right-to-automate" tabindex="-1">Cadence: Earning The Right To Automate <a class="header-anchor" href="#cadence-earning-the-right-to-automate" aria-label="Permalink to &quot;Cadence: Earning The Right To Automate&quot;">​</a></h2><p>Cadence is things running while you sleep, and it&#39;s the step you have to earn.</p><p>You earn it by proving your skills are battle tested and finding the right use cases. Because as you add more AI, the cost goes up, the risk goes up, and the maintenance goes up. Automating something doesn&#39;t mean you forget about it. You still need visibility, you still check in, and someone still owns it.</p><p>From there it comes down to the trigger.</p><p>→ Manual: you ask for it, so maybe it stays in your AI OS</p><p>→ Event: a new email, a new customer books a call, and a process kicks off</p><p>→ Schedule: every Monday, or every Sunday night</p><p>And the ways to deploy are wide open. Claude Code routines, loops, deterministic scripts on something like Modal, even having your Claude OS build an n8n automation that you push into n8n. Pick what fits your use case.</p><p>Here&#39;s the part you cannot skip. A prompt is never a permission layer.</p><p>Assume that if it can, it will. If it could send an email, it might. If it could read that database, it will.</p><p>We learned this the hard way. An agent proactively picked up a task from a list, interpreted it wrong, decided it needed to write a discount code, and sent it to 150,000 to 200,000 people on our list. A code that was never supposed to go out. We had to issue an apology.</p><p>I wasn&#39;t mad at the person who built it. We turned it into a case study so the whole team understood the risk and how to work safely. We almost needed that to learn.</p><p>The fix is keys, not prompts. If an agent doesn&#39;t have the key to the room where it can send an email, it physically cannot send one. That&#39;s a permission layer you can actually trust. Then you fix the instruction so it never happens again, and you keep looping. Every slip is data, not failure.</p><h2 id="my-usage-tips" tabindex="-1">My Usage Tips <a class="header-anchor" href="#my-usage-tips" aria-label="Permalink to &quot;My Usage Tips&quot;">​</a></h2><p>Three things I do to get more out of it.</p><p>1️⃣ Treat it as a thought partner, with a grain of salt. Don&#39;t ask how to do something, get an answer, and say go. Brainstorm with it, make it play devil&#39;s advocate while you do too, and spin up sub-agents for different perspectives. I love having sub-agents or agent teams debate each other so I can make a more informed call based on my gut. These models still lean sycophantic and want to please you, so keep that in mind.</p><p>2️⃣ Have it interview you. I use a skill called Grill Me, originally from Matt Pocock, that I tweaked to write brainstorm docs. It grills me with 15, 25, 30 questions and pulls knowledge out of my head into the OS. You can literally tell a fresh setup to use Grill Me to learn everything about your business. I ran one today to plan this entire video.</p><p>3️⃣ Verify its own work. This is the most important one. On that relationship-map build, I told it this was a demo for YouTube so it didn&#39;t need to be production ready, just easy to understand, and then to use a dynamic workflow to verify everything was accurate and worked. Have it visually check the result and test that a beginner, a software engineer, and a business owner could all click through and get it. Open a Playwright browser and click around. However you&#39;d verify an intern&#39;s work, give Claude Code that same ability. That&#39;s the difference between a 70% first pass and a 92% one.</p><h2 id="it-s-just-folders-and-files" tabindex="-1">It&#39;s Just Folders And Files <a class="header-anchor" href="#it-s-just-folders-and-files" aria-label="Permalink to &quot;It&#39;s Just Folders And Files&quot;">​</a></h2><p>The model and the harness are just the engine. The system is what you&#39;re building.</p><p>At the end of the day, all of this is folders and files. So who cares if you switch to Codex tomorrow, or back to Sonnet 4.5? Every coding agent can use it.</p><p>That&#39;s why I keep a .claude, a .codex, and a .agents, plus a claude.md and an agents.md. I want this thing as tool agnostic as possible. I run it daily with Codex too, just to see what&#39;s better.</p><p>You&#39;re not learning Claude Code or learning Codex. You&#39;re learning everything at once, because you&#39;re building your own repeatable IP. Folders and markdown files, skills and routing logic, logs and wikis. Not a Claude Code AI OS, your own personal operating system.</p><p>That should take the pressure off chasing every new drop. One day you might run your own harness on an open source model without being technical at all, and it&#39;ll just happen.</p><h2 id="lightning-round" tabindex="-1">Lightning Round <a class="header-anchor" href="#lightning-round" aria-label="Permalink to &quot;Lightning Round&quot;">​</a></h2><p>A few questions I get all the time.</p><p>→ What does it cost to run all day? Depends. I&#39;m doing knowledge work, not heavy coding, on the $200/month plan. I rarely hit my five-hour limit, and only sometimes my weekly one.</p><p>→ Where does my data go? With Claude models, to Anthropic. It&#39;s closed source, so if you&#39;re handling a lot of sensitive data you may not want a closed-source model.</p><p>→ Do I need to code? No.</p><p>→ Day one, empty folder, first move? Use the AIS OS GitHub repo I&#39;m dropping in my free Skool community with the course. Follow it and you&#39;re running in a day.</p><p>→ When it confidently gets something wrong? Check the work, then tell it to update its Claude.md and skills so it never happens again. Always make it show you the exact source for its data.</p><p>→ How do live connections work? APIs or CLIs. Search the tool&#39;s API docs, hand that to Claude Code or have it do the research, and tell it the exact endpoints. Use scoped API keys so a key can only read your meeting transcripts, not edit or delete anything. Keys, not prompts.</p><p>→ What if I ignore it for a few weeks? Nothing too bad. You just sync your data back in.</p><p>→ Does everyone on the team build their own? Yes, but learn it first so you can teach them and hand off team-wide skills. Decide where shared knowledge lives, ClickUp or Slack or Notion or Drive, and give everyone read-only access. The worst case is everyone duplicating knowledge and work, and the real blocker is always adoption.</p><h2 id="wrap" tabindex="-1">Wrap <a class="header-anchor" href="#wrap" aria-label="Permalink to &quot;Wrap&quot;">​</a></h2><p>You&#39;re not building a Claude Code AI OS. You&#39;re building your own second brain, in folders and files, that any model can plug into.</p><p>I walk through all of it step by step in the full video. Link in the first reply.</p>',137)])])}const y=t(i,[["render",s]]);export{c as __pageData,y as default};
